mapper.insert:
INSERT INTO cps_issue_draft (
  creator_emp_no, creator_emp_name, title, inspection_type_code,
  factory, area, draft_data, status, submitted_issue_id
) VALUES (
  #{creatorEmpNo}, #{creatorEmpName}, #{title}, #{inspectionTypeCode},
  #{factory}, #{area}, #{draftData}, #{status}, #{submittedIssueId}
)

mapper.update:
UPDATE cps_issue_draft
SET title = #{title},
    inspection_type_code = #{inspectionTypeCode},
    factory = #{factory},
    area = #{area},
    draft_data = #{draftData}
WHERE id = #{id}
  AND creator_emp_no = #{creatorEmpNo}
  AND status = 'ACTIVE'

mapper.select:
SELECT 
FROM cps_issue_draft
WHERE creator_emp_no = #{creatorEmpNo}
  AND status = #{status}
ORDER BY updated_at DESC
LIMIT #{limit}

mapper.update:
UPDATE cps_issue_draft
SET status = 'SUBMITTED',
    submitted_issue_id = #{submittedIssueId}
WHERE id = #{id}
  AND creator_emp_no = #{creatorEmpNo}
  AND status = 'ACTIVE'

mapper.delete:
DELETE FROM cps_issue_draft
WHERE id = #{id}
  AND creator_emp_no = #{creatorEmpNo}
